import { type Damage, settleClaim } from "./claims";
import type { InsuredItem } from "./insured-item";
import { openPolicy, type Policy } from "./policy";
import { type Customer, isAfterFirstQuote, quotePremium } from "./premium";

export type { InsuredItem } from "./insured-item";

export interface QuoteStep {
  op: "quote";
  items: InsuredItem[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export interface Scenario {
  customer: Customer;
  steps: (QuoteStep | ClaimStep)[];
}

export interface StepResult {
  premium?: number;
  payout?: number;
  remainingCap?: number;
}

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  // A policy is identified by the zero-based index of the quote step that created it.
  const policiesByQuoteStep = new Map<number, Policy>();
  let quotesSoFar = 0;
  const results = scenario.steps.map((step, stepIndex): StepResult => {
    if (step.op === "claim") return settleClaim(step.incident.damages, policiesByQuoteStep.get(step.policy) as Policy);
    policiesByQuoteStep.set(stepIndex, openPolicy(step.items));
    return { premium: quotePremium(step.items, scenario.customer, isAfterFirstQuote(quotesSoFar++)) };
  });
  return { results };
}
import type { InsuredItem } from "./insured-item";
import { drawFromCap, type Policy } from "./policy";
import { reimbursement } from "./reimbursement";

export interface Damage {
  itemType: string;
  amount: number;
}

// Payouts are rounded down to whole G, in MHPCO's favor.
function roundPayoutInMhpcoFavor(exactPayout: number): number {
  return Math.floor(exactPayout);
}

interface DamagedItem {
  damage: Damage;
  insuredItem: InsuredItem;
}

// Each reported damage refers to the next not-yet-damaged insured item of its type, in reporting order;
// a damage for which no such item remains is not covered by the policy and the claim is refused.
// Item types unknown to the price list can never be insured, so damages to them are refused by the same rule.
function matchDamagesToInsuredItems(damages: Damage[], policy: Policy): DamagedItem[] {
  const undamagedItems = [...policy.items];
  return damages.map((damage) => {
    const index = undamagedItems.findIndex((item) => item.type === damage.itemType);
    if (index === -1) throw new Error(`Damage to ${damage.itemType} is not covered by the policy`);
    return { damage, insuredItem: undamagedItems.splice(index, 1)[0] };
  });
}

function totalReimbursement(damages: Damage[], policy: Policy): number {
  return matchDamagesToInsuredItems(damages, policy).reduce(
    (sum, { damage, insuredItem }) => sum + reimbursement(damage.amount, insuredItem),
    0,
  );
}

export function settleClaim(damages: Damage[], policy: Policy): { payout: number; remainingCap: number } {
  const negativeDamage = damages.find((damage) => damage.amount < 0);
  if (negativeDamage) throw new Error(`Damage amount must not be negative: ${negativeDamage.amount}`);
  const payout = drawFromCap(policy, roundPayoutInMhpcoFavor(totalReimbursement(damages, policy)));
  return { payout, remainingCap: policy.remainingCap };
}
import type { InsuredItem } from "./insured-item";
import { unitInsuranceValue } from "./price-list";

// A policy's payout cap: the total payout per policy is capped at twice the insurance sum.
const CAP_FACTOR = 2;

export interface Policy {
  items: InsuredItem[];
  remainingCap: number;
}

// The insurance sum uses each item's price-list insurance value; premium-only rules such as curse surcharges
// or the building-block discount do not change it.
function insuranceSum(items: InsuredItem[]): number {
  return items.reduce((sum, item) => sum + unitInsuranceValue(item.type), 0);
}

export function openPolicy(items: InsuredItem[]): Policy {
  return { items, remainingCap: CAP_FACTOR * insuranceSum(items) };
}

// Pays out at most what is left of the policy's cap and deducts the payout from it.
export function drawFromCap(policy: Policy, payout: number): number {
  const cappedPayout = Math.min(payout, policy.remainingCap);
  policy.remainingCap -= cappedPayout;
  return cappedPayout;
}
import type { InsuredItem } from "./insured-item";

// The MHPCO reimbursement clauses: what a single damage event to an insured item pays out.
const DEDUCTIBLE = 100;
const HIGH_ENCHANTMENT_CLAUSE_LEVEL = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_SHARE = 0.5;
const FULL_REIMBURSEMENT_SHARE = 1;

// Claim clause threshold; independent of the premium's high-enchantment surcharge threshold.
function fallsUnderHighEnchantmentClause(damagedItem: InsuredItem): boolean {
  return (damagedItem.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAUSE_LEVEL;
}

// Which reimbursement clause applies to the damaged item: the share of the damage amount MHPCO covers.
// The high-enchantment clause wins over the dragon-material clause; dragon material is fully reimbursed,
// which coincides with the standard full reimbursement.
function reimbursementShare(damagedItem: InsuredItem): number {
  return fallsUnderHighEnchantmentClause(damagedItem) ? HIGH_ENCHANTMENT_REIMBURSEMENT_SHARE : FULL_REIMBURSEMENT_SHARE;
}

// The deductible is taken per damage event; a damage below the deductible reimburses nothing, never a negative amount.
function afterDeductible(coveredAmount: number): number {
  return Math.max(0, coveredAmount - DEDUCTIBLE);
}

// What MHPCO reimburses for a single damaged item: the covered share first, then the deductible.
export function reimbursement(damageAmount: number, damagedItem: InsuredItem): number {
  return afterDeductible(damageAmount * reimbursementShare(damagedItem));
}
export interface InsuredItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}
